const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '解：设未知数为 x' },
      { kind: 'text', payload: '由题意列方程' },
      { kind: 'text', payload: '移项得' }
    ];
  },
  render: function (input, metrics) {
    var lines = ['解：设未知数为 x', '由题意列方程', '移项得'];
    var startX = 28;
    var startY = 48;
    var lineHeight = 34;
    var fontSize = 20;
    var children = [];
    for (var i = 0; i < lines.length; i++) {
      children.push({
        type: 'label',
        x: startX,
        y: startY + i * lineHeight,
        text: lines[i],
        fontSize: fontSize,
        fill: '#1f2937',
        anchor: 'start',
        fontFamily: 'sans-serif'
      });
    }
    return {
      schemaVersion: 1,
      sceneId: 'source-transcription-clean',
      revision: input.revision,
      viewBox: {
        x: 0,
        y: 0,
        width: input.viewport.widthDu,
        height: input.viewport.heightDu
      },
      paths: [],
      root: { type: 'group', children: children }
    };
  }
};
